    let mut score = 0.0;

    // Penalize small gaps to avoid dead space
    if post_residual < 15 {
        score -= (15 - post_residual) as f64 * 10.0;
    }

    // Favor using bins with less open slots
    score += 1.0 / (open_bins_count + 1) as f64;

    // Penalize if no fitting bins are available except the current one
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    score
}

