pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Favor bins with larger remaining capacity
    if post_residual > 50 {
        score -= 1.0;
    } else if post_residual > 30 {
        score -= 0.75;
    } else if post_residual > 10 {
        score -= 0.5;
    }

    // Penalize bins where the next item will not fit
    if next_item_size != 0 && next_item_size > post_residual {
        score += 2.0;
    }

    // Favor bins with fewer open bins remaining
    if open_bins_count < total_items / 2 {
        score -= 1.0;
    } else if open_bins_count < total_items * 3 / 4 {
        score -= 0.5;
    }

    // Penalize bins where the mean residual is high
    if mean_residual > 20.0 {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Reward bins with more space left
    if bin_residual > 75 {
        score += 1.8;
    } else if bin_residual > 50 {
        score += 0.9;
    }

    // Penalize creating new bins unless necessary
    if open_bins_count == 0 && fitting_bins_count == 0 {
        score -= 2.5;
    } else if open_bins_count > 0 && fitting_bins_count == 0 {
        score -= 0.8 * (open_bins_count as f64);
    }

    // Reward bins that can fit the next item
    if post_residual >= next_item_size {
        score += 1.4;
    } else if post_residual < next_item_size && fitting_bins_count > 0 {
        score += 0.8 * (fitting_bins_count as f64);
    }

    // Penalize bins with very low residual space
    if bin_residual < 20 {
        score -= 3.5;
    } else if bin_residual < 40 {
        score -= 1.7;
    }

    // Reward bins that have a higher mean residual
    if mean_residual > 65 {
        score += 1.2 * (mean_residual / 65.0);
    }

    // Penalize late steps in the process
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.9 {
        score -= 1.8 * (progress - 0.9);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, _bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let stream_progress = (step_index as f64 / total_items as f64).powi(2);
    let residual_penalty = -(post_residual.powi(2) * 0.1).exp();
    let mut score = post_residual as f64 - stream_progress + residual_penalty;

    if post_residual < mean_residual {
        score -= (mean_residual - post_residual) * 2.0;
    }

    // Lookahead trade-offs
    let lookahead_factor = 0.5;
    if step_index < total_items / 3 {
        score += lookahead_factor * ((total_items - step_index) as f64 / total_items as f64);
    } else if step_index > 2 * total_items / 3 {
        score -= lookahead_factor * ((step_index - total_items / 3) as f64 / (total_items / 3) as f64);
    }

    // Fine-tuned thresholds
    let small_mean_residual_threshold = mean_residual * 0.7;
    if post_residual < small_mean_residual_threshold {
        score -= (small_mean_residual_threshold - post_residual) * 1.5;
    }

    score
}

